package com.stayhaven.service;
import com.stayhaven.domain.*;
import com.stayhaven.repo.*;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.time.*;
import java.util.*;
import java.time.Instant;

@Service public class BookingService {
 private final BookingRepository bookings; private final RoomRepository rooms; private final com.stayhaven.repo.RoomUnitRepository units; private final com.stayhaven.repo.RoomStatusHistoryRepository history; private final com.stayhaven.repo.OfferRepository offers; private final com.stayhaven.repo.LoyaltyTransactionRepository loyalty; private final com.stayhaven.repo.PaymentRepository payments;
 public BookingService(BookingRepository b,RoomRepository r,com.stayhaven.repo.RoomUnitRepository u,com.stayhaven.repo.RoomStatusHistoryRepository h,com.stayhaven.repo.OfferRepository o,com.stayhaven.repo.LoyaltyTransactionRepository l,com.stayhaven.repo.PaymentRepository p){bookings=b;rooms=r;units=u;history=h;offers=o;loyalty=l;payments=p;}
 @Transactional public Booking create(Account account,Long roomId,LocalDate in,LocalDate out,int guests,String guestName,String guestEmail){
  return create(account,roomId,in,out,guests,guestName,guestEmail,null,0);
 }
 @Transactional public Booking create(Account account,Long roomId,LocalDate in,LocalDate out,int guests,String guestName,String guestEmail,String offerCode){return create(account,roomId,in,out,guests,guestName,guestEmail,offerCode,0);}
 @Transactional public Booking create(Account account,Long roomId,LocalDate in,LocalDate out,int guests,String guestName,String guestEmail,String offerCode,int loyaltyPoints){
  if(in==null||out==null||!in.isAfter(LocalDate.now(ZoneId.of("Asia/Kolkata")))||!out.isAfter(in)) throw new IllegalArgumentException("Choose a future check-in date and a check-out date after check-in.");
  Room room=rooms.findByIdForUpdate(roomId).orElseThrow(()->new IllegalArgumentException("Room type not found."));
  if(guests<1||guests>room.getCapacity())throw new IllegalArgumentException("Guest count exceeds room capacity.");
  if(bookings.countOverlapping(roomId,in,out)>=room.getQuantity())throw new IllegalArgumentException("This room type is fully booked for those dates.");
  RoomUnit unit=units.findByRoomId(roomId).stream().filter(u->!"MAINTENANCE".equals(u.getStatus())&&!"CLEANING".equals(u.getStatus())&&bookings.countOverlappingUnit(u.getId(),in,out)==0).findFirst().orElseThrow(()->new IllegalArgumentException("No bookable room is available for those dates."));
  Booking b=new Booking(); b.setAccount(account);b.setRoom(room);b.setRoomUnit(unit);b.setCheckIn(in);b.setCheckOut(out);b.setGuests(guests);b.setGuestName(guestName);b.setGuestEmail(guestEmail);
  double total=room.getPricePerNight()*java.time.temporal.ChronoUnit.DAYS.between(in,out);b.setTotalPrice(total);if(offerCode!=null&&!offerCode.isBlank()){var offer=offers.findByCodeIgnoreCase(offerCode.trim()).orElseThrow(()->new IllegalArgumentException("Offer code is not valid."));if(!offer.isActive()||offer.getStartsOn()==null||offer.getEndsOn()==null||in.isBefore(offer.getStartsOn())||in.isAfter(offer.getEndsOn()))throw new IllegalArgumentException("Offer is inactive or outside its validity dates.");if(offer.getApplicableRoomType()!=null&&!offer.getApplicableRoomType().isBlank()&&!offer.getApplicableRoomType().equalsIgnoreCase(room.getType()))throw new IllegalArgumentException("Offer does not apply to this room type.");double discount="PERCENT".equals(offer.getDiscountType())?total*offer.getDiscountValue()/100.0:offer.getDiscountValue();if(discount<=0||discount>=total)throw new IllegalArgumentException("Offer discount is invalid for this booking.");b.setTotalPrice(Math.round((total-discount)*100.0)/100.0);b.setOffer(offer);}if(loyaltyPoints<0||loyaltyPoints%100!=0||loyaltyPoints>loyalty.balance(account.getId())||loyaltyPoints>=b.getTotalPrice())throw new IllegalArgumentException("Redeem points in multiples of 100, up to your available balance and booking total.");b.setTotalPrice(Math.round((b.getTotalPrice()-loyaltyPoints)*100.0)/100.0);b.setPaymentStatus("PAYMENT REQUIRED"); b.setReference("SH"+UUID.randomUUID().toString().replace("-","").substring(0,10).toUpperCase(Locale.ROOT));Booking saved=bookings.save(b);if(loyaltyPoints>0){var t=new LoyaltyTransaction();t.setGuest(account);t.setBooking(saved);t.setPoints(-loyaltyPoints);t.setType("REDEEM");t.setReason("Booking redemption at ₹1 per point (100 point minimum)");loyalty.save(t);}return saved;
 }
 @Transactional public Booking updateStatus(Long bookingId,String status){
  if(!"CONFIRMED".equals(status)&&!"CANCELLED".equals(status)&&!"PENDING".equals(status))throw new IllegalArgumentException("Unsupported booking status.");
  Booking booking=bookings.findById(bookingId).orElseThrow(()->new IllegalArgumentException("Booking not found."));
  Room room=rooms.findByIdForUpdate(booking.getRoom().getId()).orElseThrow(()->new IllegalArgumentException("Room type not found."));
  if(("CONFIRMED".equals(status)||"PENDING".equals(status))&&!("CONFIRMED".equals(booking.getStatus())||"PENDING".equals(booking.getStatus()))){
   if("DEMO REFUND REQUIRED".equals(booking.getPaymentStatus()))throw new IllegalArgumentException("A cancelled booking with a recorded demo payment cannot be reopened; create a new booking.");
   if(!booking.getCheckIn().isAfter(LocalDate.now(ZoneId.of("Asia/Kolkata"))))throw new IllegalArgumentException("Past or current bookings cannot be confirmed.");
   if(bookings.countOverlapping(room.getId(),booking.getCheckIn(),booking.getCheckOut())>=room.getQuantity())throw new IllegalArgumentException("Room inventory is full for those dates.");
  }
  if("CANCELLED".equals(status)){payments.findByBookingId(booking.getId()).ifPresent(p->{p.setStatus("TEST_REFUND_REQUIRED");payments.save(p);booking.setPaymentStatus("DEMO REFUND REQUIRED");});}booking.setStatus(status);return bookings.save(booking);
 }
 @Transactional public Booking checkIn(Long id,Account staff){Booking b=bookings.findById(id).orElseThrow(()->new IllegalArgumentException("Booking not found."));if(!"CONFIRMED".equals(b.getStatus()))throw new IllegalArgumentException("Only a confirmed booking can be checked in.");if(!b.getCheckIn().equals(LocalDate.now(ZoneId.of("Asia/Kolkata"))))throw new IllegalArgumentException("Check-in is only available on the scheduled arrival date.");if(b.getRoomUnit()==null)throw new IllegalArgumentException("No room has been assigned to this booking.");RoomUnit u=units.findWithRoomById(b.getRoomUnit().getId()).orElseThrow();if(!"AVAILABLE".equals(u.getStatus()))throw new IllegalArgumentException("The assigned room is not available.");b.setStatus("CHECKED IN");b.setCheckedInAt(Instant.now());b.setCheckedInBy(staff);u.setStatus("OCCUPIED");u.setLastCheckedInAt(b.getCheckedInAt());units.save(u);history.save(new com.stayhaven.domain.RoomStatusHistory(u,staff,"AVAILABLE","OCCUPIED","Guest checked in: "+b.getReference()));return bookings.save(b);}
 @Transactional public Booking checkOut(Long id,Account staff){Booking b=bookings.findById(id).orElseThrow(()->new IllegalArgumentException("Booking not found."));if(!"CHECKED IN".equals(b.getStatus()))throw new IllegalArgumentException("Only a checked-in booking can be checked out.");b.setStatus("CHECKED OUT");b.setCheckedOutAt(Instant.now());b.setCheckedOutBy(staff);RoomUnit u=b.getRoomUnit();u.setStatus("CLEANING");u.setLastCheckedOutAt(b.getCheckedOutAt());units.save(u);history.save(new com.stayhaven.domain.RoomStatusHistory(u,staff,"OCCUPIED","CLEANING","Guest checked out: "+b.getReference()));if(!loyalty.existsByBookingIdAndType(b.getId(),"EARN")){var t=new LoyaltyTransaction();t.setGuest(b.getAccount());t.setBooking(b);t.setPoints((int)Math.floor(b.getTotalPrice()/100.0));t.setType("EARN");t.setReason("Earn 1 point per ₹100 completed stay value");if(t.getPoints()>0)loyalty.save(t);}return bookings.save(b);}
 @Transactional public void updateRoomStatus(Long roomUnitId,String status,Account staff){if(!java.util.Set.of("AVAILABLE","CLEANING","MAINTENANCE").contains(status))throw new IllegalArgumentException("Unsupported room status.");RoomUnit u=units.findWithRoomById(roomUnitId).orElseThrow(()->new IllegalArgumentException("Room not found."));if("OCCUPIED".equals(u.getStatus()))throw new IllegalArgumentException("An occupied room cannot be marked ready or taken out of service.");if("AVAILABLE".equals(status)&&bookings.findAll().stream().anyMatch(b->b.getRoomUnit()!=null&&b.getRoomUnit().getId().equals(roomUnitId)&&"CHECKED IN".equals(b.getStatus())))throw new IllegalArgumentException("A guest is still checked in.");String old=u.getStatus();u.setStatus(status);units.save(u);history.save(new com.stayhaven.domain.RoomStatusHistory(u,staff,old,status,"Room status updated by administrator"));}
}
